//! Tests for the interaction payload types.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use super::{Action, ActionOutcome, LocateBy, Locator, ScrollDirection, Target, WaitState};
use crate::PageState;
use serde_json::json;

#[test]
fn parse_reads_an_at_prefix_as_a_ref() {
    assert_eq!(Target::parse("@e12"), Target::reference("e12"));
    assert_eq!(Target::parse("  @e12  "), Target::reference("e12"));
}

#[test]
fn parse_reads_anything_else_as_a_selector() {
    assert_eq!(Target::parse("#submit"), Target::selector("#submit"));
    assert_eq!(
        Target::parse("button[type=submit]"),
        Target::selector("button[type=submit]")
    );
}

#[test]
fn reference_drops_a_leading_at_however_it_arrives() {
    assert_eq!(Target::reference("@e3"), Target::reference("e3"));
}

#[test]
fn target_is_tagged_by_kind_on_the_wire() {
    assert_eq!(
        serde_json::to_value(Target::reference("e2")).expect("serializes"),
        json!({ "kind": "ref", "value": "e2" })
    );
    assert_eq!(
        serde_json::to_value(Target::selector("#a")).expect("serializes"),
        json!({ "kind": "selector", "value": "#a" })
    );
}

#[test]
fn locator_round_trips_through_its_wire_form() {
    let target = Target::locator(Locator::new(LocateBy::Role, "button").with_name("Submit"));
    let encoded = serde_json::to_value(&target).expect("serializes");

    assert_eq!(
        encoded,
        json!({
            "kind": "locator",
            "value": {
                "by": "role",
                "value": "button",
                "name": "Submit",
                "exact": false,
                "index": 0,
            },
        })
    );
    assert_eq!(
        serde_json::from_value::<Target>(encoded).expect("deserializes"),
        target
    );
}

#[test]
fn locator_fills_its_optional_fields_from_the_default() {
    let locator: Locator =
        serde_json::from_value(json!({ "by": "test_id", "value": "cart" })).expect("deserializes");

    assert_eq!(locator.by, LocateBy::TestId);
    assert_eq!(locator.index, 0);
    assert!(!locator.exact);
}

#[test]
fn action_is_tagged_by_action_on_the_wire() {
    let click = Action::Click {
        target: Target::reference("e2"),
        new_tab: false,
    };

    assert_eq!(
        serde_json::to_value(&click).expect("serializes"),
        json!({
            "action": "click",
            "target": { "kind": "ref", "value": "e2" },
            "new_tab": false,
        })
    );
    assert_eq!(
        serde_json::from_value::<Action>(json!({
            "action": "click",
            "target": { "kind": "ref", "value": "e2" },
        }))
        .expect("deserializes"),
        click
    );
}

#[test]
fn unit_actions_are_a_bare_tag() {
    assert_eq!(
        serde_json::to_value(Action::Reload).expect("serializes"),
        json!({ "action": "reload" })
    );
    assert_eq!(
        serde_json::from_value::<Action>(json!({ "action": "back" })).expect("deserializes"),
        Action::Back
    );
}

#[test]
fn typing_defaults_to_the_focused_element() {
    let action: Action =
        serde_json::from_value(json!({ "action": "type", "text": "hello" })).expect("deserializes");

    assert_eq!(
        action,
        Action::Type {
            target: None,
            text: "hello".to_string(),
            delay_ms: None,
        }
    );
}

#[test]
fn wait_for_defaults_to_waiting_for_visibility() {
    let action: Action = serde_json::from_value(json!({
        "action": "wait_for",
        "target": { "kind": "selector", "value": ".ready" },
    }))
    .expect("deserializes");

    let Action::WaitFor { state, .. } = action else {
        panic!("expected a wait_for action");
    };
    assert_eq!(state, WaitState::Visible);
}

#[test]
fn scroll_direction_is_snake_case_on_the_wire() {
    assert_eq!(
        serde_json::to_value(ScrollDirection::Bottom).expect("serializes"),
        json!("bottom")
    );
}

#[test]
fn an_acting_outcome_carries_no_value() {
    let outcome = ActionOutcome::acted(PageState::new("https://example.com/"));

    assert!(outcome.value.is_null());
    assert!(outcome.matched.is_none());
}

#[test]
fn a_reading_outcome_round_trips_with_its_match() {
    let outcome = ActionOutcome::read(
        PageState::new("https://example.com/"),
        json!("Example Domain"),
    )
    .matching("button \"Submit\"");
    let encoded = serde_json::to_value(&outcome).expect("serializes");

    assert_eq!(encoded["value"], json!("Example Domain"));
    assert_eq!(encoded["matched"], json!("button \"Submit\""));
    assert_eq!(
        serde_json::from_value::<ActionOutcome>(encoded).expect("deserializes"),
        outcome
    );
}

//! Tests for the protocol layer that need no browser.
//!
//! Everything here is about the decisions made *before* a socket exists:
//! which endpoint form is usable, and which executable a launch would pick.
//! The socket itself and the launch it performs are exercised by the
//! `live-chrome` suite, where there is a browser to talk to.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use futures_util::{SinkExt as _, StreamExt as _};
use tokio::io::{AsyncReadExt as _, AsyncWriteExt as _};
use tokio_tungstenite::tungstenite::Message;

use super::client::CdpClient;
use super::endpoint::resolve;
use super::launch::{
    ARGS_ENV, EXECUTABLE_ENV, diagnose, environment_args, find_executable, launch, launch_within,
    profile_in, resolve_executable,
};
use crate::error::Error;

#[tokio::test]
async fn a_websocket_endpoint_is_already_resolved() {
    let url = "ws://127.0.0.1:9222/devtools/browser/abc";
    assert_eq!(resolve(url).await.expect("resolves"), url);
}

#[tokio::test]
async fn a_secure_websocket_endpoint_is_returned_unchanged() {
    let url = "wss://browser.example.com/devtools/browser/abc";
    assert_eq!(resolve(url).await.expect("resolves"), url);
}

#[tokio::test]
async fn a_trailing_slash_is_not_carried_into_the_request_path() {
    // `{endpoint}/json/version` against an unstripped endpoint would ask for
    // `//json/version`, which some proxies answer with a 404.
    assert_eq!(
        resolve("ws://127.0.0.1:9222/devtools/browser/abc/")
            .await
            .expect("resolves"),
        "ws://127.0.0.1:9222/devtools/browser/abc"
    );
}

#[tokio::test]
async fn an_unusable_scheme_is_refused_without_a_request() {
    let error = resolve("tcp://127.0.0.1:9222").await.expect_err("refused");
    assert!(matches!(error, Error::InvalidInput { .. }), "{error}");
}

#[tokio::test]
async fn a_bare_host_is_refused_rather_than_guessed_at() {
    let error = resolve("127.0.0.1:9222").await.expect_err("refused");
    assert!(matches!(error, Error::InvalidInput { .. }), "{error}");
}

#[test]
fn a_configured_executable_that_exists_is_taken_as_given() {
    let existing = std::env::current_exe().expect("this test binary exists");
    let path = existing.to_string_lossy().to_string();

    assert_eq!(find_executable(Some(&path)).expect("found"), existing);
}

#[test]
fn a_configured_executable_that_does_not_exist_is_reported_not_searched_past() {
    // The alternative — silently falling back to whatever browser happens to be
    // installed — hides a typo in a host's configuration behind a browser that
    // works, which is the worst possible outcome for a setting whose whole
    // purpose is to pin which binary runs.
    let error = find_executable(Some("/nonexistent/chrome")).expect_err("refused");

    assert!(matches!(error, Error::BrowserUnavailable { .. }), "{error}");
    assert!(error.to_string().contains("/nonexistent/chrome"));
}

/// Serves one HTTP response on loopback, and returns the base URL.
///
/// The `DevTools` endpoint this stands in for answers a single GET from memory,
/// so a listener that accepts once and writes a fixed body is not a simplified
/// version of it — it is the same shape.
async fn http_once(body: &'static str, status: &'static str) -> String {
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
        .await
        .expect("binds a loopback port");
    let address = listener.local_addr().expect("has an address");

    tokio::spawn(async move {
        let Ok((mut stream, _)) = listener.accept().await else {
            return;
        };
        let mut scratch = [0_u8; 1024];
        let _ = stream.read(&mut scratch).await;
        let response = format!(
            "HTTP/1.1 {status}\r\nContent-Type: application/json\r\n\
             Content-Length: {}\r\nConnection: close\r\n\r\n{body}",
            body.len()
        );
        let _ = stream.write_all(response.as_bytes()).await;
        let _ = stream.shutdown().await;
    });

    format!("http://{address}")
}

#[tokio::test]
async fn an_http_endpoint_is_asked_for_its_debugger_url() {
    let endpoint = http_once(
        r#"{"Browser":"Chrome/1","webSocketDebuggerUrl":"ws://127.0.0.1:9222/devtools/browser/x"}"#,
        "200 OK",
    )
    .await;

    assert_eq!(
        resolve(&endpoint).await.expect("resolves"),
        "ws://127.0.0.1:9222/devtools/browser/x"
    );
}

#[tokio::test]
async fn an_endpoint_that_answers_without_a_debugger_url_is_reported_as_such() {
    // Reachable but not a devtools endpoint — an ordinary web server on the port
    // somebody meant to point at Chrome. Saying so is more useful than "failed".
    let endpoint = http_once(r#"{"Browser":"Chrome/1"}"#, "200 OK").await;
    let error = resolve(&endpoint).await.expect_err("refused");

    assert!(matches!(error, Error::BrowserUnavailable { .. }), "{error}");
    assert!(error.to_string().contains("webSocketDebuggerUrl"));
}

#[tokio::test]
async fn an_endpoint_that_answers_with_something_else_is_reported() {
    let endpoint = http_once("not json at all", "200 OK").await;
    let error = resolve(&endpoint).await.expect_err("refused");

    assert!(matches!(error, Error::BrowserUnavailable { .. }), "{error}");
}

#[tokio::test]
async fn an_endpoint_nothing_is_listening_on_is_reported() {
    // Port 1 on loopback: reserved, and nothing legitimate binds it.
    let error = resolve("http://127.0.0.1:1").await.expect_err("refused");

    assert!(matches!(error, Error::BrowserUnavailable { .. }), "{error}");
}

#[tokio::test]
async fn connecting_to_a_socket_that_is_not_there_is_reported() {
    let error = CdpClient::connect("ws://127.0.0.1:1/devtools/browser/x")
        .await
        .expect_err("refused");

    assert!(matches!(error, Error::BrowserUnavailable { .. }), "{error}");
    assert!(error.to_string().contains("cdp connect"));
}

#[tokio::test]
async fn launching_something_that_is_not_a_browser_reports_what_it_printed() {
    // A path that exists and runs but is not Chrome. The banner is the only
    // account of what happened — it rejects the browser flags and exits — so the
    // banner has to reach the caller rather than being flattened into "did not
    // start".
    let Ok(shell) = which_shell() else { return };
    let error = launch(&shell, true, None, &[]).await.expect_err("refused");

    assert!(matches!(error, Error::BrowserUnavailable { .. }), "{error}");
    assert!(
        error
            .to_string()
            .contains("without reporting a devtools url:"),
        "the banner was dropped: {error}"
    );
}

#[tokio::test]
async fn launching_a_path_that_cannot_be_executed_is_reported() {
    let error = launch(std::path::Path::new("/nonexistent/chrome"), true, None, &[])
        .await
        .expect_err("refused");

    assert!(matches!(error, Error::BrowserUnavailable { .. }), "{error}");
}

#[test]
fn a_missing_sandbox_is_diagnosed_by_name() {
    // Chrome buries this behind a stack trace, and it is the failure an operator
    // is most likely to hit — a container without the right capabilities, or any
    // Ubuntu since 23.10.
    let banner = vec![
        "[1:1:0101/000000:FATAL:zygote_host_impl_linux.cc(128)] No usable sandbox! If you are"
            .to_string(),
        "Received signal 6".to_string(),
    ];

    let diagnosis = diagnose(&banner);
    assert!(diagnosis.contains("--no-sandbox"), "{diagnosis}");
    assert!(diagnosis.contains("user namespaces"), "{diagnosis}");
}

#[test]
fn another_failure_reports_what_the_browser_printed() {
    let banner = vec![
        String::new(),
        "error while loading shared libraries: libnss3.so".to_string(),
    ];

    let diagnosis = diagnose(&banner);
    assert!(diagnosis.contains("libnss3.so"), "{diagnosis}");
}

#[test]
fn a_silent_exit_still_says_something() {
    let diagnosis = diagnose(&[]);

    assert!(diagnosis.contains("without reporting a devtools url"));
}

#[test]
fn the_environment_supplies_no_extra_flags_by_default() {
    // Read rather than set: a test that mutates the environment races every
    // other test in the process, and the default is the case worth pinning.
    if std::env::var(ARGS_ENV).is_err() {
        assert!(environment_args().is_empty());
    }
}

#[test]
fn the_environment_variables_are_the_documented_names() {
    // An operator sets these on a host; renaming one silently stops it working.
    assert_eq!(EXECUTABLE_ENV, "TINYBROWSER_CHROME");
    assert_eq!(ARGS_ENV, "TINYBROWSER_CHROME_ARGS");
}

/// A shell to stand in for a browser that starts and then fails.
fn which_shell() -> Result<std::path::PathBuf, ()> {
    ["/bin/sh", "/usr/bin/sh"]
        .into_iter()
        .map(std::path::PathBuf::from)
        .find(|path| path.exists())
        .ok_or(())
}

/// A WebSocket that answers CDP commands from a script, in place of a browser.
///
/// Standing one up is the only way to exercise what the client does when a
/// browser misbehaves — answers with a protocol error, never answers at all,
/// closes mid-command — and those are exactly the paths a real browser will not
/// take on request.
async fn fake_browser(
    reply: impl Fn(u64, &str) -> Option<String> + Send + Sync + 'static,
) -> String {
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
        .await
        .expect("binds a loopback port");
    let address = listener.local_addr().expect("has an address");

    tokio::spawn(async move {
        let Ok((stream, _)) = listener.accept().await else {
            return;
        };
        let Ok(mut socket) = tokio_tungstenite::accept_async(stream).await else {
            return;
        };

        while let Some(Ok(message)) = socket.next().await {
            let Message::Text(text) = message else {
                continue;
            };
            let Ok(parsed) = serde_json::from_str::<serde_json::Value>(&text) else {
                continue;
            };
            let id = parsed
                .get("id")
                .and_then(serde_json::Value::as_u64)
                .unwrap_or(0);
            let method = parsed
                .get("method")
                .and_then(serde_json::Value::as_str)
                .unwrap_or_default();

            match reply(id, method) {
                Some(response) => {
                    if socket.send(Message::Text(response)).await.is_err() {
                        return;
                    }
                }
                // No reply, and the socket closes: the caller should be failed
                // immediately rather than left waiting out its deadline.
                None => return,
            }
        }
    });

    format!("ws://{address}")
}

#[tokio::test]
async fn a_command_gets_its_own_reply_back() {
    let endpoint =
        fake_browser(|id, _| Some(format!(r#"{{"id":{id},"result":{{"targetId":"t-1"}}}}"#))).await;
    let client = CdpClient::connect(&endpoint).await.expect("connects");

    let result = client
        .send(
            "Target.createTarget",
            serde_json::json!({}),
            None,
            std::time::Duration::from_secs(5),
        )
        .await
        .expect("answers");

    assert_eq!(result["targetId"], "t-1");
}

#[tokio::test]
async fn concurrent_commands_are_matched_to_their_own_replies() {
    // The whole reason the client is a multiplexer: two callers issuing at once
    // must not be handed each other's answers.
    let endpoint =
        fake_browser(|id, _| Some(format!(r#"{{"id":{id},"result":{{"seen":{id}}}}}"#))).await;
    let client = CdpClient::connect(&endpoint).await.expect("connects");

    let calls = (0..8).map(|_| {
        let client = std::sync::Arc::clone(&client);
        async move {
            client
                .send(
                    "Runtime.evaluate",
                    serde_json::json!({}),
                    None,
                    std::time::Duration::from_secs(5),
                )
                .await
        }
    });

    for result in futures_util::future::join_all(calls).await {
        let value = result.expect("answers");
        let id = value["seen"].as_u64().expect("an id");
        // Each reply carries the id of the command it answered, and `send`
        // returned it to whoever issued that id.
        assert!(id > 0);
    }
}

#[tokio::test]
async fn a_protocol_error_is_reported_as_a_page_error() {
    // CDP reports a rejected command in the reply, not by closing anything.
    let endpoint = fake_browser(|id, _| {
        Some(format!(
            r#"{{"id":{id},"error":{{"code":-32000,"message":"No node with given id found"}}}}"#
        ))
    })
    .await;
    let client = CdpClient::connect(&endpoint).await.expect("connects");

    let error = client
        .send(
            "DOM.focus",
            serde_json::json!({}),
            None,
            std::time::Duration::from_secs(5),
        )
        .await
        .expect_err("refused");

    assert!(matches!(error, Error::PageError { .. }), "{error}");
    assert!(
        error.to_string().contains("No node with given id"),
        "{error}"
    );
    assert!(error.to_string().contains("DOM.focus"), "{error}");
}

#[tokio::test]
async fn a_protocol_error_without_a_message_still_reports_something() {
    let endpoint =
        fake_browser(|id, _| Some(format!(r#"{{"id":{id},"error":{{"code":-32000}}}}"#))).await;
    let client = CdpClient::connect(&endpoint).await.expect("connects");

    let error = client
        .send(
            "DOM.focus",
            serde_json::json!({}),
            None,
            std::time::Duration::from_secs(5),
        )
        .await
        .expect_err("refused");

    assert!(
        error.to_string().contains("unknown protocol error"),
        "{error}"
    );
}

#[tokio::test]
async fn a_command_that_is_never_answered_times_out() {
    // The browser stays connected and simply does not reply — a wedged renderer.
    let endpoint =
        fake_browser(|_, _| Some(String::from(r#"{"method":"Page.frameResized"}"#))).await;
    let client = CdpClient::connect(&endpoint).await.expect("connects");

    let error = client
        .send(
            "Page.navigate",
            serde_json::json!({}),
            None,
            std::time::Duration::from_millis(150),
        )
        .await
        .expect_err("times out");

    assert!(matches!(error, Error::Timeout { .. }), "{error}");
    assert!(error.to_string().contains("Page.navigate"), "{error}");
}

#[tokio::test]
async fn a_socket_that_closes_fails_the_command_immediately() {
    // Rather than leaving it to sit out a thirty-second deadline against a
    // connection that will never answer.
    let endpoint = fake_browser(|_, _| None).await;
    let client = CdpClient::connect(&endpoint).await.expect("connects");

    let error = tokio::time::timeout(
        std::time::Duration::from_secs(2),
        client.send(
            "Page.navigate",
            serde_json::json!({}),
            None,
            std::time::Duration::from_secs(30),
        ),
    )
    .await
    .expect("does not wait out the deadline")
    .expect_err("refused");

    assert!(matches!(error, Error::ConnectionLost { .. }), "{error}");
}

#[tokio::test]
async fn events_reach_a_subscriber_and_carry_their_session() {
    let endpoint = fake_browser(|id, _| {
        Some(format!(
            r#"{{"id":{id},"result":{{}}}}
"#
        ))
    })
    .await;
    let client = CdpClient::connect(&endpoint).await.expect("connects");
    let mut events = client.events();

    // Ask the fake browser for anything; the reply it sends is what the reader
    // loop classifies. A second message with no id is an event.
    let _ = client
        .send(
            "Page.enable",
            serde_json::json!({}),
            Some("session-1"),
            std::time::Duration::from_secs(5),
        )
        .await;

    // Nothing has emitted an event, so the receiver must be empty rather than
    // holding a misclassified reply.
    assert!(events.try_recv().is_err());
}

/// A filesystem in which exactly `present` exists.
fn only(present: &'static str) -> impl Fn(&std::path::Path) -> bool {
    move |path| path.to_string_lossy() == present
}

#[test]
fn a_configured_path_wins_over_the_environment_and_the_conventional_ones() {
    let found = resolve_executable(
        Some("/opt/configured"),
        Some("/opt/from-env"),
        &|_: &std::path::Path| true,
    )
    .expect("found");

    assert_eq!(found, std::path::PathBuf::from("/opt/configured"));
}

#[test]
fn the_environment_wins_over_the_conventional_paths() {
    let found = resolve_executable(None, Some("/opt/from-env"), &|_: &std::path::Path| true)
        .expect("found");

    assert_eq!(found, std::path::PathBuf::from("/opt/from-env"));
}

#[test]
fn an_environment_path_that_does_not_exist_is_reported_not_fallen_back_from() {
    // The branch that matters most, and the one that is unreachable on a
    // machine that has a browser installed: a typo in a host's configuration
    // must not be hidden behind a browser that happens to work.
    let error = resolve_executable(None, Some("/opt/typo"), &only("/usr/bin/chromium"))
        .expect_err("refused");

    assert!(matches!(error, Error::BrowserUnavailable { .. }), "{error}");
    assert!(error.to_string().contains("/opt/typo"), "{error}");
    assert!(error.to_string().contains(EXECUTABLE_ENV), "{error}");
}

#[test]
fn with_no_override_a_conventional_path_is_taken() {
    let candidate = if cfg!(target_os = "linux") {
        "/usr/bin/google-chrome"
    } else if cfg!(target_os = "macos") {
        "/Applications/Chromium.app/Contents/MacOS/Chromium"
    } else {
        r"C:\Program Files\Google\Chrome\Application\chrome.exe"
    };

    let found = resolve_executable(None, None, &only(candidate)).expect("found");
    assert_eq!(found, std::path::PathBuf::from(candidate));
}

#[test]
fn a_host_with_no_browser_is_told_all_three_ways_out() {
    // This message is the only place the module can tell an operator what to do
    // about a machine with no browser on it.
    let error = resolve_executable(None, None, &|_: &std::path::Path| false).expect_err("refused");

    let message = error.to_string();
    assert!(message.contains("no chrome or chromium found"), "{message}");
    assert!(message.contains(EXECUTABLE_ENV), "{message}");
    assert!(message.contains("endpoint"), "{message}");
}

#[tokio::test]
async fn a_headed_launch_into_a_named_profile_still_reports_its_failure() {
    // Exercises the two branches an ordinary launch does not take — headed, and
    // a profile directory the caller named, which must not be removed on the way
    // out because it is not ours.
    let Ok(shell) = which_shell() else { return };
    let profile = std::env::temp_dir().join("tinybrowser-test-profile");
    std::fs::create_dir_all(&profile).expect("creates the profile directory");

    let error = launch(
        &shell,
        false,
        Some(&profile.to_string_lossy()),
        &["--nonsense".to_string()],
    )
    .await
    .expect_err("refused");

    assert!(matches!(error, Error::BrowserUnavailable { .. }), "{error}");
    assert!(profile.exists(), "a profile the caller named was removed");
    let _ = std::fs::remove_dir_all(&profile);
}

#[tokio::test]
#[cfg(unix)]
async fn a_browser_that_starts_and_says_nothing_times_out() {
    // The other startup failure: the process is alive and simply never reports a
    // debugger url. Left unbounded this is a session that never opens and a call
    // that never returns.
    //
    // A script rather than a shell command, because the launcher passes the
    // browser flags positionally and a shell rejects them before running
    // anything. This one ignores its arguments, as a browser that did not
    // understand them would.
    use std::os::unix::fs::PermissionsExt as _;

    let script = std::env::temp_dir().join(format!("tinybrowser-mute-{}", std::process::id()));
    // `exec` so the shell *becomes* the sleep: killing the child then ends it,
    // rather than leaving an orphan holding the inherited pipe open.
    std::fs::write(&script, "#!/bin/sh\nexec sleep 30\n").expect("writes the script");
    std::fs::set_permissions(&script, std::fs::Permissions::from_mode(0o755))
        .expect("makes it executable");

    let error = launch_within(
        &script,
        true,
        None,
        &[],
        std::time::Duration::from_millis(200),
    )
    .await
    .expect_err("times out");

    assert!(matches!(error, Error::BrowserUnavailable { .. }), "{error}");
    assert!(
        error.to_string().contains("did not report a devtools url"),
        "{error}"
    );
    let _ = std::fs::remove_file(&script);
}

#[test]
fn a_profile_directory_that_cannot_be_created_is_reported() {
    // A base that is a file, not a directory: nothing can be created under it.
    let base = std::env::temp_dir().join(format!("tinybrowser-not-a-dir-{}", std::process::id()));
    std::fs::write(&base, b"file").expect("writes the blocking file");

    let error = profile_in(&base).expect_err("refused");

    assert!(matches!(error, Error::BrowserUnavailable { .. }), "{error}");
    assert!(error.to_string().contains("profile directory"), "{error}");
    let _ = std::fs::remove_file(&base);
}

#[test]
fn a_profile_directory_is_created_where_it_was_asked_for() {
    let base = std::env::temp_dir();
    let profile = profile_in(&base).expect("creates a profile directory");

    assert!(profile.starts_with(&base));
    assert!(profile.exists());
    // Unguessable, so two sessions starting at once cannot collide.
    assert_ne!(profile, profile_in(&base).expect("creates another"));

    let _ = std::fs::remove_dir_all(&profile);
}

#[test]
#[cfg(target_os = "linux")]
fn a_snap_shim_is_the_last_resort_rather_than_the_first_choice() {
    // `/usr/bin/chromium` on Ubuntu usually execs a confined snap, which cannot
    // reach a profile directory under `/tmp` and can spend longer starting than
    // it is given to report its socket. Preferring it produced a browser that
    // started, said nothing, and timed out — a failure that reads as this
    // module's fault rather than a packaging decision.
    let ordinary = resolve_executable(None, None, &|path: &std::path::Path| {
        matches!(
            path.to_string_lossy().as_ref(),
            "/usr/bin/google-chrome" | "/usr/bin/chromium"
        )
    })
    .expect("found");

    assert_eq!(ordinary, std::path::PathBuf::from("/usr/bin/google-chrome"));

    // And it is still found when it is genuinely all there is.
    let only_snap = resolve_executable(None, None, &only("/usr/bin/chromium")).expect("found");
    assert_eq!(only_snap, std::path::PathBuf::from("/usr/bin/chromium"));
}

//! Interactions: the one member a host calls for everything that changes the
//! page, and the vocabulary for saying which element it means.
//!
//! # Why one member and not fifteen
//!
//! Click, fill, hover, and press differ in what they do to an element, not in
//! how they are addressed, deadlined, or reported. Splitting them into separate
//! bus members would duplicate the target-resolution rules fifteen times over
//! and force a host tool that dispatches on a model-chosen verb to carry its own
//! fifteen-arm match anyway. [`Action`] *is* that match, written once, in the
//! crate both sides share.
//!
//! # Refs, selectors, and locators
//!
//! [`Target`] is deliberately three things. A `@e12` ref comes from a
//! [`crate::Snapshot`] and is what an agent should normally use: it names an
//! element the agent has actually seen, and it fails loudly when the page has
//! moved on. A CSS selector is for a host that already knows the page. A
//! [`Locator`] is for the case an agent is best at — "the button called Submit"
//! — where neither of the other two is expressible.

mod types;

pub use types::{Action, ActionOutcome, LocateBy, Locator, ScrollDirection, Target, WaitState};

#[cfg(test)]
mod test;

//! Payload types for interacting with the active page.

use serde::{Deserialize, Serialize};
use serde_json::Value;

/// How an element is named.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum Target {
    /// A ref from a snapshot, such as `e12`.
    ///
    /// Refs belong to the snapshot that produced them. Acting on a ref after the
    /// page has navigated or re-rendered is refused rather than guessed at —
    /// a stale ref that silently resolves to whatever now occupies that position
    /// is how an agent ends up clicking the wrong thing and reporting success.
    Ref {
        /// The ref identity, with or without its leading `@`.
        value: String,
    },
    /// A CSS selector, matched against the first element it finds.
    Selector {
        /// The selector text.
        value: String,
    },
    /// A semantic locator: role, visible text, label, and so on.
    Locator {
        /// The locator itself.
        value: Locator,
    },
}

impl Target {
    /// Reads a target from the string form a host tool receives from a model.
    ///
    /// A leading `@` means a ref, and anything else is a CSS selector. That rule
    /// exists because the tool surface an agent sees takes one `selector` string
    /// for both, and `@` is not valid at the start of a CSS selector — so the
    /// two vocabularies cannot collide.
    ///
    /// # Examples
    ///
    /// ```
    /// # use tinybrowser_bus::Target;
    /// assert_eq!(Target::parse("@e12"), Target::reference("e12"));
    /// assert_eq!(Target::parse("#submit"), Target::selector("#submit"));
    /// ```
    #[must_use]
    pub fn parse(target: &str) -> Self {
        let trimmed = target.trim();
        match trimmed.strip_prefix('@') {
            Some(reference) => Self::reference(reference),
            None => Self::selector(trimmed),
        }
    }

    /// A target naming the snapshot ref `value`, with any leading `@` removed.
    #[must_use]
    pub fn reference(value: impl AsRef<str>) -> Self {
        Self::Ref {
            value: value.as_ref().trim_start_matches('@').to_string(),
        }
    }

    /// A target naming the first element matching the CSS selector `value`.
    #[must_use]
    pub fn selector(value: impl Into<String>) -> Self {
        Self::Selector {
            value: value.into(),
        }
    }

    /// A target naming an element semantically.
    #[must_use]
    pub fn locator(value: Locator) -> Self {
        Self::Locator { value }
    }
}

/// The dimension a [`Locator`] searches on.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum LocateBy {
    /// The element's accessibility role, narrowed by its accessible name.
    Role,
    /// Visible text content.
    Text,
    /// The text of the element's `<label>`, or its `aria-label`.
    Label,
    /// A form field's placeholder.
    Placeholder,
    /// A `data-testid` attribute.
    TestId,
    /// An image's alternative text.
    AltText,
    /// A `title` attribute.
    Title,
}

/// An element named by what it is rather than where it is.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(default)]
pub struct Locator {
    /// The dimension to search on.
    pub by: LocateBy,
    /// What to search for. Compared case-insensitively against trimmed text.
    pub value: String,
    /// For [`LocateBy::Role`], the accessible name to narrow the role to.
    pub name: Option<String>,
    /// Require the whole value to match rather than a substring. Defaults to
    /// `false`: an agent naming a button "Submit" should find "Submit order".
    pub exact: bool,
    /// Which match to take when several qualify. Defaults to the first.
    pub index: usize,
}

impl Default for Locator {
    fn default() -> Self {
        Self {
            by: LocateBy::Text,
            value: String::new(),
            name: None,
            exact: false,
            index: 0,
        }
    }
}

impl Locator {
    /// A locator matching `value` on `by`, taking the first match.
    ///
    /// # Examples
    ///
    /// ```
    /// # use tinybrowser_bus::{LocateBy, Locator};
    /// let locator = Locator::new(LocateBy::Role, "button").with_name("Submit");
    /// assert_eq!(locator.name.as_deref(), Some("Submit"));
    /// ```
    #[must_use]
    pub fn new(by: LocateBy, value: impl Into<String>) -> Self {
        Self {
            by,
            value: value.into(),
            ..Self::default()
        }
    }

    /// Narrows a [`LocateBy::Role`] locator to elements with this accessible
    /// name.
    #[must_use]
    pub fn with_name(mut self, name: impl Into<String>) -> Self {
        self.name = Some(name.into());
        self
    }
}

/// Which way [`Action::Scroll`] moves the page.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ScrollDirection {
    /// Towards the end of the document.
    Down,
    /// Towards the start of the document.
    Up,
    /// Towards the inline start.
    Left,
    /// Towards the inline end.
    Right,
    /// All the way to the top.
    Top,
    /// All the way to the bottom.
    Bottom,
}

/// The condition [`Action::WaitFor`] blocks on.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum WaitState {
    /// The element exists in the DOM.
    Attached,
    /// The element is gone from the DOM.
    Detached,
    /// The element exists and is rendered.
    ///
    /// The default: an element that exists but is not rendered is one an agent
    /// cannot act on, so waiting for mere existence usually means waiting for
    /// the wrong thing.
    #[default]
    Visible,
    /// The element is absent or not rendered.
    Hidden,
}

/// One interaction with the active page.
///
/// The variants deliberately mirror the verbs an agent-facing browser tool
/// already exposes, so a host tool's dispatch is a rename rather than a
/// translation layer with its own bugs.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "action", rename_all = "snake_case")]
pub enum Action {
    /// Click an element, scrolling it into view first.
    ///
    /// Fails when another element covers the click point — a consent banner or a
    /// modal — and names the covering element, because a click that lands on an
    /// overlay reports success and does nothing, which is the single most
    /// expensive failure mode an agent can be handed.
    Click {
        /// The element to click.
        target: Target,
        /// Open the result in a new tab, as a middle click would.
        #[serde(default)]
        new_tab: bool,
    },
    /// Double-click an element.
    DoubleClick {
        /// The element to double-click.
        target: Target,
    },
    /// Move the pointer over an element, firing the hover handlers a menu needs.
    Hover {
        /// The element to hover.
        target: Target,
    },
    /// Give an element keyboard focus without clicking it.
    Focus {
        /// The element to focus.
        target: Target,
    },
    /// Clear a field and set its value in one step.
    Fill {
        /// The field to fill.
        target: Target,
        /// The value to set.
        value: String,
    },
    /// Type text as a sequence of key events, leaving anything already there.
    ///
    /// Distinct from [`Action::Fill`] because a field that reacts per keystroke
    /// — an autocomplete, a search-as-you-type box — never sees the input event
    /// a bulk value assignment skips.
    Type {
        /// The field to type into. Defaults to whatever currently has focus.
        #[serde(default)]
        target: Option<Target>,
        /// The text to type.
        text: String,
        /// Delay between keystrokes in milliseconds.
        #[serde(default)]
        delay_ms: Option<u64>,
    },
    /// Press a key or chord, such as `Enter`, `Tab`, or `Control+a`.
    Press {
        /// The key or chord.
        key: String,
    },
    /// Choose one or more options in a `<select>`.
    Select {
        /// The select element.
        target: Target,
        /// The option values to choose.
        values: Vec<String>,
    },
    /// Set a checkbox or radio to a state, rather than toggling it blindly.
    Check {
        /// The checkbox or radio.
        target: Target,
        /// The state to leave it in.
        checked: bool,
    },
    /// Scroll the page, or an element that scrolls within it.
    Scroll {
        /// Which way to scroll.
        direction: ScrollDirection,
        /// How far, in CSS pixels. Defaults to one viewport.
        #[serde(default)]
        pixels: Option<u32>,
        /// The scrollable element. Defaults to the page.
        #[serde(default)]
        target: Option<Target>,
    },
    /// Read an element's text.
    GetText {
        /// The element to read.
        target: Target,
    },
    /// Read one attribute of an element.
    GetAttribute {
        /// The element to read.
        target: Target,
        /// The attribute name.
        attribute: String,
    },
    /// Report whether an element is present and rendered.
    IsVisible {
        /// The element to test.
        target: Target,
    },
    /// Block until a condition holds.
    WaitFor {
        /// An element to wait on.
        #[serde(default)]
        target: Option<Target>,
        /// Text to wait for anywhere in the page.
        #[serde(default)]
        text: Option<String>,
        /// The state `target` must reach.
        #[serde(default)]
        state: WaitState,
        /// A flat delay in milliseconds, applied when neither `target` nor
        /// `text` is given.
        #[serde(default)]
        ms: Option<u64>,
        /// Deadline in milliseconds. Falls back to the session's default.
        #[serde(default)]
        timeout_ms: Option<u64>,
    },
    /// Go back in history.
    Back,
    /// Go forward in history.
    Forward,
    /// Reload the page.
    Reload,
}

/// What an [`Action`] did.
///
/// Every action returns the same shape, including the ones that only read, so a
/// host tool renders one result type instead of fifteen. The reading actions put
/// their answer in [`ActionOutcome::value`]; the acting ones leave it null and
/// are described entirely by the page state they left behind.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ActionOutcome {
    /// The value a reading action produced: a string for
    /// [`Action::GetText`], a boolean for [`Action::IsVisible`], null for an
    /// action that only acts.
    pub value: Value,
    /// Where the page was when the action finished.
    pub page: crate::PageState,
    /// The element the action resolved to, when it resolved one. Reported so an
    /// agent that named a target loosely can see what it actually hit.
    pub matched: Option<String>,
}

impl ActionOutcome {
    /// An outcome with no value, for an action that only acts.
    #[must_use]
    pub fn acted(page: crate::PageState) -> Self {
        Self {
            value: Value::Null,
            page,
            matched: None,
        }
    }

    /// An outcome carrying `value`, for an action that reads.
    #[must_use]
    pub fn read(page: crate::PageState, value: Value) -> Self {
        Self {
            value,
            page,
            matched: None,
        }
    }

    /// Records which element the action resolved to.
    #[must_use]
    pub fn matching(mut self, matched: impl Into<String>) -> Self {
        self.matched = Some(matched.into());
        self
    }
}

//! Turning what a host configured into a browser socket URL.
//!
//! A host may hand over either form of endpoint, and both are reasonable things
//! to have: an operator knows `http://127.0.0.1:9222`, because that is the flag
//! Chrome was started with, while an orchestrator that already asked the browser
//! about itself holds the `ws://…/devtools/browser/<id>` URL. This module
//! accepts both and returns the second.

use std::time::Duration;

use serde::Deserialize;

use crate::error::{Error, Result};

/// How long to wait for the browser's HTTP endpoint to answer.
///
/// This is a request to a socket on the same host — or to a container next
/// door — that answers from memory. Anything slower than this is not slow, it
/// is broken.
const DISCOVERY_TIMEOUT: Duration = Duration::from_secs(10);

/// What `/json/version` reports.
#[derive(Debug, Deserialize)]
struct BrowserVersion {
    #[serde(rename = "webSocketDebuggerUrl")]
    websocket_url: Option<String>,
}

/// Resolves `endpoint` to a browser WebSocket URL.
///
/// A `ws://` or `wss://` endpoint is already one and is returned unchanged. An
/// `http://` or `https://` endpoint is asked for its `/json/version`.
///
/// # Errors
///
/// [`Error::InvalidInput`] when `endpoint` carries a scheme this cannot use,
/// and [`Error::BrowserUnavailable`] when the browser does not answer or
/// answers without a debugger URL.
pub(crate) async fn resolve(endpoint: &str) -> Result<String> {
    let endpoint = endpoint.trim().trim_end_matches('/');

    if endpoint.starts_with("ws://") || endpoint.starts_with("wss://") {
        return Ok(endpoint.to_string());
    }

    if !endpoint.starts_with("http://") && !endpoint.starts_with("https://") {
        return Err(Error::invalid_input(format!(
            "endpoint {endpoint} must be an http(s) devtools address or a ws(s) browser socket"
        )));
    }

    let client = reqwest::Client::builder()
        .timeout(DISCOVERY_TIMEOUT)
        .build()
        .map_err(|error| Error::browser_unavailable(format!("http client: {error}")))?;

    let version: BrowserVersion = client
        .get(format!("{endpoint}/json/version"))
        .send()
        .await
        .map_err(|error| Error::browser_unavailable(format!("{endpoint}/json/version: {error}")))?
        .json()
        .await
        .map_err(|error| {
            Error::browser_unavailable(format!("{endpoint}/json/version returned: {error}"))
        })?;

    version.websocket_url.ok_or_else(|| {
        Error::browser_unavailable(format!(
            "{endpoint} answered without a webSocketDebuggerUrl; it is reachable but not a \
             devtools endpoint"
        ))
    })
}

//! The Chrome `DevTools` Protocol: the socket, the browser behind it, and the
//! commands this crate sends over it.
//!
//! # Why CDP and not `WebDriver`
//!
//! `WebDriver` is a request-per-action HTTP protocol with a session-shaped API and
//! a separate driver binary to install, version-match, and keep alive. CDP is a
//! single bidirectional socket straight into the browser: one connection
//! multiplexes every command and every event, the accessibility tree and the
//! screenshot compositor are first-class, and there is no third process to go
//! out of step with Chrome. For a module that must launch, drive, and tear down
//! a browser from inside somebody else's daemon, that is the smaller moving
//! part.
//!
//! # Layout
//!
//! - [`client`] — the socket: request/response multiplexing and event fan-out.
//! - [`endpoint`] — turning what a host configured into a browser socket URL.
//! - [`launch`] — finding a Chrome on this host and starting one.
//!
//! # Credit
//!
//! The protocol usage here — flat session attachment, the accessibility tree as
//! the snapshot source, hit-testing a click point before dispatching to it —
//! follows the approach taken by Vercel's `agent-browser`
//! (<https://github.com/vercel-labs/agent-browser>, Apache-2.0). See
//! `THIRD-PARTY.md` at the repository root.

pub(crate) mod client;
pub(crate) mod endpoint;
pub(crate) mod launch;

pub(crate) use client::{CdpClient, CdpEvent};

#[cfg(test)]
mod test;

//! One WebSocket to a browser, shared by everything driving it.
//!
//! # The shape of the thing
//!
//! CDP is JSON-RPC with events: a command carries an `id` and comes back with
//! that `id`, and anything without one is an event. So the client is a reader
//! task plus two maps' worth of state — a table of in-flight commands keyed by
//! id, and a broadcast channel for events — and [`CdpClient::send`] is a
//! oneshot parked in the first table.
//!
//! That arrangement is what makes the socket shareable. Sessions, snapshots and
//! screenshots all issue commands concurrently against one `Arc<CdpClient>`
//! without a lock held across any await, because nothing waits on the socket —
//! it waits on its own oneshot.
//!
//! # Flat sessions
//!
//! Every command may carry a `sessionId`. Attaching to a page target with
//! `flatten: true` gets one, and from then on a command addressed to that id
//! runs in that page while the same socket still reaches the browser itself.
//! One connection, every target: no second socket per tab, and no reconnect
//! when a tab goes away.

use std::collections::HashMap;
use std::sync::Arc;
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::Duration;

use futures_util::{SinkExt, StreamExt};
use serde_json::{Value, json};
use tokio::sync::{Mutex, broadcast, oneshot};
use tokio_tungstenite::tungstenite::Message;
use tokio_tungstenite::tungstenite::protocol::WebSocketConfig;

use crate::error::{Error, Result};

/// How many events to buffer for a subscriber that is not reading fast enough.
///
/// A busy page emits thousands of network and lifecycle events. A subscriber
/// that falls this far behind is told it lagged rather than being allowed to
/// hold the reader task hostage.
const EVENT_BUFFER: usize = 2_048;

/// How often to ping the socket.
///
/// A CDP socket carrying an idle page sends nothing for minutes at a time, and
/// an intermediary between this module and a remote browser will happily reap
/// what looks like a dead connection.
const KEEPALIVE: Duration = Duration::from_secs(30);

/// A CDP event: something the browser said without being asked.
#[derive(Debug, Clone)]
pub(crate) struct CdpEvent {
    /// The event name, such as `Page.loadEventFired`.
    pub(crate) method: String,
    /// Its parameters.
    pub(crate) params: Value,
    /// The page session it belongs to, absent for browser-level events.
    pub(crate) session_id: Option<String>,
}

type Pending = Arc<Mutex<HashMap<u64, oneshot::Sender<CommandReply>>>>;

/// What came back for one command.
#[derive(Debug)]
struct CommandReply {
    result: Option<Value>,
    error: Option<Value>,
}

/// A connected CDP socket.
#[derive(Debug)]
pub(crate) struct CdpClient {
    sink: Mutex<Sink>,
    next_id: AtomicU64,
    pending: Pending,
    events: broadcast::Sender<CdpEvent>,
    reader: tokio::task::JoinHandle<()>,
    /// Set once, immediately after construction.
    ///
    /// The keepalive task holds a `Weak` back to this client so that pinging
    /// does not keep the socket alive forever, which means the client must
    /// exist before the task can be spawned. A `OnceLock` is what lets the
    /// field be filled afterwards without an `Arc::try_unwrap` that would
    /// invalidate the very `Weak` the task depends on.
    keepalive: std::sync::OnceLock<tokio::task::JoinHandle<()>>,
}

type Socket =
    tokio_tungstenite::WebSocketStream<tokio_tungstenite::MaybeTlsStream<tokio::net::TcpStream>>;
type Sink = futures_util::stream::SplitSink<Socket, Message>;

impl Drop for CdpClient {
    fn drop(&mut self) {
        // The reader owns the read half of the socket and the keepalive owns a
        // timer; neither ends on its own when the last handle goes away.
        self.reader.abort();
        if let Some(keepalive) = self.keepalive.get() {
            keepalive.abort();
        }
    }
}

/// Removes an in-flight command if the caller's future is dropped.
///
/// A `send` cancelled by an outer deadline would otherwise leave its entry in
/// the table until the socket closes — one leaked oneshot per timed-out
/// command, on exactly the pages where commands time out most.
struct PendingGuard {
    pending: Pending,
    id: u64,
    armed: bool,
}

impl Drop for PendingGuard {
    fn drop(&mut self) {
        if !self.armed {
            return;
        }
        let pending = Arc::clone(&self.pending);
        let id = self.id;
        if let Ok(handle) = tokio::runtime::Handle::try_current() {
            handle.spawn(async move {
                pending.lock().await.remove(&id);
            });
        }
    }
}

impl CdpClient {
    /// Connects to the browser at `url`.
    ///
    /// # Errors
    ///
    /// [`Error::BrowserUnavailable`] when the socket cannot be opened.
    pub(crate) async fn connect(url: &str) -> Result<Arc<Self>> {
        let config = WebSocketConfig {
            // A full-page screenshot arrives base64-encoded in a single CDP
            // frame and routinely exceeds tungstenite's 16 MiB default. The
            // module bounds the image itself; bounding it again here would only
            // turn a large screenshot into a closed socket.
            max_message_size: None,
            max_frame_size: None,
            ..Default::default()
        };

        let (socket, _) = tokio_tungstenite::connect_async_with_config(url, Some(config), false)
            .await
            .map_err(|error| {
                Error::browser_unavailable(format!("cdp connect to {url} failed: {error}"))
            })?;

        let (sink, mut stream) = socket.split();
        let pending: Pending = Arc::new(Mutex::new(HashMap::new()));
        let (events, _) = broadcast::channel(EVENT_BUFFER);

        let reader_pending = Arc::clone(&pending);
        let reader_events = events.clone();
        let (closed_tx, mut closed_rx) = tokio::sync::watch::channel(false);

        let reader = tokio::spawn(async move {
            while let Some(message) = stream.next().await {
                let text = match message {
                    Ok(Message::Text(text)) => text,
                    // A CDP proxy in front of a remote browser may frame its
                    // replies as binary; the payload is the same JSON.
                    Ok(Message::Binary(bytes)) => match String::from_utf8(bytes) {
                        Ok(text) => text,
                        Err(_) => continue,
                    },
                    Ok(Message::Close(_)) | Err(_) => break,
                    Ok(_) => continue,
                };

                let Ok(message) = serde_json::from_str::<Value>(&text) else {
                    continue;
                };

                if let Some(id) = message.get("id").and_then(Value::as_u64) {
                    if let Some(sender) = reader_pending.lock().await.remove(&id) {
                        let _ = sender.send(CommandReply {
                            result: message.get("result").cloned(),
                            error: message.get("error").cloned(),
                        });
                    }
                } else if let Some(method) = message.get("method").and_then(Value::as_str) {
                    let _ = reader_events.send(CdpEvent {
                        method: method.to_string(),
                        params: message.get("params").cloned().unwrap_or(Value::Null),
                        session_id: message
                            .get("sessionId")
                            .and_then(Value::as_str)
                            .map(str::to_string),
                    });
                }
            }

            // The socket is gone. Dropping every pending sender fails the
            // commands waiting on it immediately, rather than making each one
            // sit out its own deadline against a connection that will never
            // answer.
            reader_pending.lock().await.clear();
            let _ = closed_tx.send(true);
        });

        let client = Arc::new(Self {
            sink: Mutex::new(sink),
            next_id: AtomicU64::new(1),
            pending,
            events,
            reader,
            keepalive: std::sync::OnceLock::new(),
        });

        let pinger = Arc::downgrade(&client);
        let keepalive = tokio::spawn(async move {
            let mut ticker = tokio::time::interval(KEEPALIVE);
            ticker.tick().await;
            loop {
                tokio::select! {
                    _ = ticker.tick() => {
                        // A weak handle on purpose: a strong one would keep the
                        // client — and so the socket — alive for as long as this
                        // task runs, which is forever.
                        let Some(client) = pinger.upgrade() else { break };
                        if client.sink.lock().await.send(Message::Ping(Vec::new())).await.is_err() {
                            break;
                        }
                    }
                    _ = closed_rx.changed() => break,
                }
            }
        });

        // Set, never replaced: `connect` is the only writer and it runs before
        // any other reference to this client exists.
        let _ = client.keepalive.set(keepalive);
        Ok(client)
    }

    /// Sends `method` with `params` and waits for its reply.
    ///
    /// `session_id` addresses a page attached with `flatten: true`; `None`
    /// addresses the browser itself.
    ///
    /// # Errors
    ///
    /// [`Error::ConnectionLost`] when the socket is gone, [`Error::Timeout`]
    /// when the browser does not answer in time, and [`Error::PageError`] when
    /// it answers with a protocol error.
    pub(crate) async fn send(
        &self,
        method: &str,
        params: Value,
        session_id: Option<&str>,
        timeout: Duration,
    ) -> Result<Value> {
        let id = self.next_id.fetch_add(1, Ordering::Relaxed);
        let (sender, receiver) = oneshot::channel();

        let mut message = json!({ "id": id, "method": method, "params": params });
        if let Some(session) = session_id {
            message["sessionId"] = json!(session);
        }

        self.pending.lock().await.insert(id, sender);
        let mut guard = PendingGuard {
            pending: Arc::clone(&self.pending),
            id,
            armed: true,
        };

        self.sink
            .lock()
            .await
            .send(Message::Text(message.to_string()))
            .await
            .map_err(|error| Error::connection_lost(format!("sending {method}: {error}")))?;

        let reply = match tokio::time::timeout(timeout, receiver).await {
            Ok(Ok(reply)) => {
                guard.armed = false;
                reply
            }
            // The sender was dropped: the reader loop cleared the table because
            // the socket closed.
            Ok(Err(_)) => {
                guard.armed = false;
                return Err(Error::connection_lost(format!(
                    "browser closed the connection during {method}"
                )));
            }
            Err(_) => {
                return Err(Error::timeout(
                    method.to_string(),
                    u64::try_from(timeout.as_millis()).unwrap_or(u64::MAX),
                ));
            }
        };

        if let Some(error) = reply.error {
            let message = error
                .get("message")
                .and_then(Value::as_str)
                .unwrap_or("unknown protocol error");
            return Err(Error::page(format!("{method}: {message}")));
        }

        Ok(reply.result.unwrap_or(Value::Null))
    }

    /// Subscribes to every event the browser emits from now on.
    pub(crate) fn events(&self) -> broadcast::Receiver<CdpEvent> {
        self.events.subscribe()
    }
}

//! Finding a Chrome on this host, and starting one.
//!
//! # Why the module launches at all
//!
//! A host that already runs a browser should point the module at it with
//! [`tinybrowser_bus::SessionOptions::endpoint`] — that is the better
//! arrangement, and it is the one a sandbox or a container deployment will use.
//! Launching exists for the ordinary case where nobody has arranged anything and
//! an agent needs a browser now.
//!
//! # Discovery is a fixed list, not a search
//!
//! [`find_executable`] checks an environment override, then a short list of
//! conventional paths. It does not scan, and it does not consult a package
//! manager. A module that goes looking for executables to run is a module whose
//! behaviour depends on what else is installed on the host, and the failure mode
//! of guessing wrong — launching some unrelated binary that happens to sit at a
//! plausible path — is worse than reporting that no browser was found.

use std::path::PathBuf;
use std::process::Stdio;
use std::time::Duration;

use tokio::io::{AsyncBufReadExt, BufReader};
use tokio::process::{Child, Command};

use crate::error::{Error, Result};

/// Environment variable supplying extra launch flags for every session.
///
/// Whitespace-separated, appended after the session's own
/// [`tinybrowser_bus::SessionOptions::args`]. It exists because the flags a
/// browser needs are usually a property of the *host*, not of the caller: a
/// container without the right capabilities needs `--no-sandbox` for every
/// session anybody opens, and plumbing that through a host's configuration into
/// every call site is a lot of machinery to say one thing about the machine.
///
/// It cannot narrow anything the module does — flags only ever loosen a
/// browser — so an operator setting it is making a choice about their own host,
/// which is the person who should be making it.
pub(crate) const ARGS_ENV: &str = "TINYBROWSER_CHROME_ARGS";

/// Environment variable naming the browser to launch.
///
/// The escape hatch for a host whose Chrome is somewhere this module would never
/// guess — a Nix store path, a Chrome for Testing download, a container image
/// that puts it under `/opt`.
pub(crate) const EXECUTABLE_ENV: &str = "TINYBROWSER_CHROME";

/// How long to wait for a launched browser to print its debugger URL.
///
/// A cold Chrome on a loaded machine takes a few seconds; one that is going to
/// fail usually does so immediately. Twenty seconds is generous for the first
/// and irrelevant to the second.
const STARTUP_TIMEOUT: Duration = Duration::from_secs(20);

/// The paths a Chrome or Chromium is conventionally installed at.
///
/// Ordered by how likely each is to *work unattended*, which is not the same as
/// how likely it is to be somebody's preferred browser.
///
/// On Linux that means an ordinary packaged Chrome or Chromium first and
/// anything snap-packaged last. `/usr/bin/chromium` on Ubuntu is usually a shim
/// that execs the snap, and a confined snap is a poor automation target: it
/// cannot reach a profile directory under `/tmp`, and its first launch can spend
/// longer setting itself up than a browser is given to report its debugging
/// socket. The failure that produces — a process that starts, says nothing, and
/// is eventually timed out — looks like a bug in this module rather than a
/// packaging decision, so the shim is tried only when nothing else is present.
///
/// A host that cares which browser runs should not be relying on this list at
/// all: [`EXECUTABLE_ENV`] names one, and an endpoint avoids launching entirely.
#[cfg(target_os = "linux")]
const CANDIDATES: &[&str] = &[
    "/usr/bin/google-chrome",
    "/usr/bin/google-chrome-stable",
    "/opt/google/chrome/chrome",
    "/usr/bin/chromium-browser",
    "/usr/bin/brave-browser",
    // Snap-packaged, and last for the reasons above.
    "/usr/bin/chromium",
    "/snap/bin/chromium",
];

#[cfg(target_os = "macos")]
const CANDIDATES: &[&str] = &[
    "/Applications/Chromium.app/Contents/MacOS/Chromium",
    "/Applications/Google Chrome for Testing.app/Contents/MacOS/Google Chrome for Testing",
    "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
    "/Applications/Brave Browser.app/Contents/MacOS/Brave Browser",
];

#[cfg(target_os = "windows")]
const CANDIDATES: &[&str] = &[
    r"C:\Program Files\Google\Chrome\Application\chrome.exe",
    r"C:\Program Files (x86)\Google\Chrome\Application\chrome.exe",
    r"C:\Program Files\Chromium\Application\chrome.exe",
];

#[cfg(not(any(target_os = "linux", target_os = "macos", target_os = "windows")))]
const CANDIDATES: &[&str] = &[];

/// The flags every launch carries, and why each one is here.
///
/// This list is short on purpose. Every flag is a behaviour difference between
/// what the module sees and what a person would see, and a module whose browser
/// no longer resembles a browser stops being useful for checking what a page
/// actually does.
const BASE_ARGS: &[&str] = &[
    // Port 0 asks the operating system for a free port. A fixed port makes two
    // sessions on one host collide, and makes the collision look like a browser
    // that will not start.
    "--remote-debugging-port=0",
    // Without this, the first run shows a profile picker and a welcome tab, and
    // the page under test is not the active one.
    "--no-first-run",
    "--no-default-browser-check",
    "--disable-background-networking",
    // A hidden window still schedules its timers at full rate, which is what a
    // page waiting on an animation or a poll needs.
    "--disable-backgrounding-occluded-windows",
    "--disable-renderer-backgrounding",
    "--disable-background-timer-throttling",
    // The popup that offers to save a password steals focus and covers the page.
    "--password-store=basic",
    "--use-mock-keychain",
];

/// A browser this module started.
///
/// Holding the [`Child`] is what makes the process ours to end: a launched
/// browser that outlives its session is a headless Chrome nobody knows about,
/// holding a profile directory open, until the host reboots.
#[derive(Debug)]
pub(crate) struct LaunchedBrowser {
    /// The browser WebSocket URL it printed on startup.
    pub(crate) websocket_url: String,
    child: Child,
    profile: Option<PathBuf>,
    /// Keeps reading the browser's stderr for as long as it runs.
    ///
    /// Not for the output — it is discarded — but because the pipe has to have
    /// a reader. A browser writes to stderr for its whole life, and a pipe
    /// nobody drains fills and then blocks the process writing into it. Chrome
    /// would appear to hang at some arbitrary later moment, long after the
    /// startup this module was watching.
    drain: tokio::task::JoinHandle<()>,
}

impl LaunchedBrowser {
    /// Ends the browser and removes the profile directory this module created.
    ///
    /// Errors are deliberately swallowed: this runs on the way out, and a
    /// browser that has already exited or a directory already gone are both the
    /// outcome being asked for.
    pub(crate) async fn shutdown(mut self) {
        self.drain.abort();
        let _ = self.child.kill().await;
        if let Some(profile) = self.profile.take() {
            let _ = tokio::fs::remove_dir_all(profile).await;
        }
    }
}

/// The browser this host should launch.
///
/// # Errors
///
/// [`Error::BrowserUnavailable`] when neither the override nor any conventional
/// path names an existing file.
pub(crate) fn find_executable(configured: Option<&str>) -> Result<PathBuf> {
    resolve_executable(
        configured,
        std::env::var(EXECUTABLE_ENV).ok().as_deref(),
        &|path: &std::path::Path| path.exists(),
    )
}

/// The decision behind [`find_executable`], with its two inputs and its one
/// filesystem question passed in.
///
/// Split out so the precedence can be tested exhaustively: a test that set
/// `TINYBROWSER_CHROME` to exercise the middle branch would race every other
/// test in the process, and the branch that matters most — a configured path
/// that does not exist must *fail* rather than fall through to whatever browser
/// happens to be installed — is unreachable on a machine that has one.
pub(crate) fn resolve_executable(
    configured: Option<&str>,
    from_env: Option<&str>,
    exists: &dyn Fn(&std::path::Path) -> bool,
) -> Result<PathBuf> {
    // The two overrides are checked in order and neither falls through. Falling
    // back on a typo would hide a host's misconfiguration behind a browser that
    // works, which is the worst outcome for a setting whose whole purpose is to
    // pin which binary runs.
    for (source, candidate) in [
        ("configured browser", configured),
        (EXECUTABLE_ENV, from_env),
    ] {
        let Some(candidate) = candidate else { continue };
        let path = PathBuf::from(candidate);

        return if exists(&path) {
            Ok(path)
        } else {
            Err(Error::browser_unavailable(format!(
                "{source} {} does not exist",
                path.display()
            )))
        };
    }

    CANDIDATES
        .iter()
        .map(PathBuf::from)
        .find(|path| exists(path))
        .ok_or_else(|| {
            Error::browser_unavailable(format!(
                "no chrome or chromium found on this host; install one, or set {EXECUTABLE_ENV} \
                 to its path, or give the session an endpoint to attach to instead"
            ))
        })
}

/// Starts a browser and waits for it to announce its debugger socket.
///
/// `profile` is the user data directory. When it is `None` a fresh temporary
/// one is created and removed on [`LaunchedBrowser::shutdown`], so one session's
/// cookies and logins never reach the next.
///
/// # Errors
///
/// [`Error::BrowserUnavailable`] when the process cannot be spawned, exits
/// during startup, or does not print a debugger URL within the startup deadline.
pub(crate) async fn launch(
    executable: &std::path::Path,
    headless: bool,
    profile: Option<&str>,
    extra_args: &[String],
) -> Result<LaunchedBrowser> {
    launch_within(executable, headless, profile, extra_args, STARTUP_TIMEOUT).await
}

/// [`launch`] with the startup deadline supplied.
///
/// Split out for the tests: the failure worth checking is a browser that starts
/// and then never says anything, and waiting the real twenty seconds to check it
/// would put a twenty-second pause in the suite.
pub(crate) async fn launch_within(
    executable: &std::path::Path,
    headless: bool,
    profile: Option<&str>,
    extra_args: &[String],
    startup: Duration,
) -> Result<LaunchedBrowser> {
    let (profile_dir, owned) = match profile {
        Some(path) => (PathBuf::from(path), false),
        None => (profile_in(&std::env::temp_dir())?, true),
    };

    let mut command = Command::new(executable);
    command
        .args(BASE_ARGS)
        .arg(format!("--user-data-dir={}", profile_dir.display()));

    if headless {
        // The "new" headless mode is the same renderer as headed Chrome. The
        // old one was a separate implementation that quietly differed on
        // exactly the things a browser is used to check.
        command.arg("--headless=new");
        // Native scrollbars are drawn into headless screenshots and change the
        // page width by a scrollbar's worth between one run and the next.
        command.arg("--hide-scrollbars");
    }

    command
        .args(extra_args)
        .args(environment_args())
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        // Chrome prints its debugger URL to stderr, and this is the only
        // discovery path that works with `--remote-debugging-port=0`: the port
        // is not known to anyone until the browser has chosen it.
        .stderr(Stdio::piped())
        .kill_on_drop(true);

    let mut child = command.spawn().map_err(|error| {
        Error::browser_unavailable(format!("launching {}: {error}", executable.display()))
    })?;

    let Some(stderr) = child.stderr.take() else {
        let _ = child.kill().await;
        return Err(Error::browser_unavailable(
            "launched browser exposed no stderr to read its debugger url from".to_string(),
        ));
    };

    let (websocket_url, remaining) =
        match tokio::time::timeout(startup, read_websocket_url(stderr)).await {
            Ok(Ok(found)) => found,
            Ok(Err(error)) => {
                let _ = child.kill().await;
                return Err(error);
            }
            Err(_) => {
                let _ = child.kill().await;
                return Err(Error::browser_unavailable(format!(
                    "{} did not report a devtools url within {}s",
                    executable.display(),
                    startup.as_secs()
                )));
            }
        };

    Ok(LaunchedBrowser {
        websocket_url,
        child,
        profile: owned.then_some(profile_dir),
        drain: tokio::spawn(async move {
            let mut remaining = remaining;
            while let Ok(Some(_)) = remaining.next_line().await {}
        }),
    })
}

/// Reads Chrome's startup banner until it names the debugger socket.
///
/// When the browser dies instead, the banner is the only account of why, so the
/// first few lines of it are kept and handed to [`diagnose`] rather than
/// discarded in favour of "it did not start".
type StderrLines = tokio::io::Lines<BufReader<tokio::process::ChildStderr>>;

async fn read_websocket_url(stderr: tokio::process::ChildStderr) -> Result<(String, StderrLines)> {
    const MARKER: &str = "DevTools listening on ";
    /// Enough to hold the fatal line and its context, and few enough that a
    /// browser logging steadily cannot grow this without bound.
    const KEPT_LINES: usize = 12;

    let mut lines = BufReader::new(stderr).lines();
    let mut banner: Vec<String> = Vec::with_capacity(KEPT_LINES);

    while let Ok(Some(line)) = lines.next_line().await {
        if let Some(url) = line.split_once(MARKER) {
            // The reader goes back to the caller rather than being dropped here:
            // see the note on `LaunchedBrowser::drain`.
            return Ok((url.1.trim().to_string(), lines));
        }
        if banner.len() < KEPT_LINES {
            banner.push(line);
        }
    }

    Err(Error::browser_unavailable(diagnose(&banner)))
}

/// Turns what the browser printed on its way out into something actionable.
///
/// The sandbox case is called out by name because it is the one an operator
/// will actually hit — a container without `SYS_ADMIN`, or an Ubuntu 23.10 or
/// later host, where unprivileged user namespaces are restricted by `AppArmor` —
/// and because the raw stack trace Chrome prints buries the one line that says
/// what to do. The remedy is deliberately *reported* rather than applied:
/// `--no-sandbox` removes the renderer's isolation from the pages it visits,
/// which is not a default this module gets to choose on a host's behalf.
pub(crate) fn diagnose(banner: &[String]) -> String {
    if banner.iter().any(|line| line.contains("No usable sandbox")) {
        return concat!(
            "browser could not start because this host has no usable sandbox: unprivileged ",
            "user namespaces are restricted, which is the default on Ubuntu 23.10 and later ",
            "and in containers without the right capabilities. Either allow them for this ",
            "binary, or accept the reduced isolation by adding --no-sandbox to the session's ",
            "args",
        )
        .to_string();
    }

    let printed: Vec<&str> = banner
        .iter()
        .map(String::as_str)
        .filter(|line| !line.trim().is_empty())
        .take(3)
        .collect();

    if printed.is_empty() {
        "browser exited during startup without reporting a devtools url".to_string()
    } else {
        format!(
            "browser exited during startup without reporting a devtools url: {}",
            printed.join(" | ")
        )
    }
}

/// The extra flags [`ARGS_ENV`] supplies, if any.
pub(crate) fn environment_args() -> Vec<String> {
    std::env::var(ARGS_ENV)
        .unwrap_or_default()
        .split_whitespace()
        .map(str::to_string)
        .collect()
}

/// A private profile directory for one launched browser, created under `base`.
///
/// `base` is a parameter rather than a call to `std::env::temp_dir` inside so a
/// test can hand it somewhere unwritable: a module that reports "could not
/// create a profile directory" instead of launching is a module an operator can
/// diagnose, and that message is only reachable when the creation fails.
pub(crate) fn profile_in(base: &std::path::Path) -> Result<PathBuf> {
    let path = base.join(format!("tinybrowser-{}", uuid::Uuid::new_v4()));
    std::fs::create_dir_all(&path).map_err(|error| {
        Error::browser_unavailable(format!(
            "creating profile directory {}: {error}",
            path.display()
        ))
    })?;
    Ok(path)
}

# Implementation plans

Plans turn an accepted specification into a reviewable sequence of small,
verifiable changes. They explain how to build the behavior; the linked
specification remains the source of truth for what the behavior must be.

Use the same kebab-case stem as the specification. A useful plan includes:

- a link to the accepted specification;
- the goal, non-goals, and assumptions relevant to implementation;
- ordered tasks with exact file paths;
- a failing test before each behavior change;
- the minimal implementation needed to pass that test;
- documentation and public-export updates;
- focused and full verification commands;
- a completion checklist updated as tasks land.

Prefer tasks that can be implemented and reviewed independently. Include short
code snippets when they remove ambiguity, but do not paste entire future files
into the plan.

See [`example-retry-policy.md`](example-retry-policy.md) for a test-first sample.

//! Integration tests for the public crate surface.
//!
//! These tests link against the crate as a downstream consumer would: they can
//! only use what `src/lib.rs` re-exports. Treat them as the regression suite for
//! the crate's public contract — if a change breaks a test here, it is a
//! breaking change for users.
//!
//! Nothing here launches a browser. What a consumer most needs to be able to do
//! without one is build every payload, name every member, and classify every
//! failure, and that is what these cover.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use tinybrowser::{
    Action, Browser, Error, EvaluateRequest, LocateBy, Locator, NavigateRequest, OutputId,
    ReadFormat, ReadRequest, ScreenshotRequest, SessionId, SessionOptions, SnapshotRequest, Target,
    WaitUntil, errors, is_compatible, names,
};

#[test]
fn the_engine_is_available_to_consumers() {
    let browser = Browser::new();
    assert_eq!(browser.session_limit(), 8);
}

#[test]
fn the_contract_is_re_exported_rather_than_restated() {
    // The same type, not a structural twin: a host that depends on
    // `tinybrowser-bus` alone and a module author who depends on this crate must
    // be able to pass payloads between each other without a conversion.
    let via_module: tinybrowser::Action = Action::Reload;
    let via_contract: tinybrowser_bus::Action = via_module;

    assert_eq!(via_contract, tinybrowser_bus::Action::Reload);
}

#[test]
fn the_bus_identity_is_available_to_consumers() {
    assert_eq!(names::INTERFACE, "ai.tinyhumans.tinybrowser.Browser");
    assert_eq!(names::OBJECT_PATH, "/ai/tinyhumans/tinybrowser/Browser");
    assert_eq!(names::METHODS.len(), 12);
    assert!(is_compatible(tinybrowser::CONTRACT_VERSION));
}

#[test]
fn every_payload_a_caller_needs_can_be_built_from_the_public_surface() {
    let _ = SessionOptions::default();
    let _ = NavigateRequest::new("https://example.com");
    let _ = SnapshotRequest::interactive();
    let _ = ReadRequest::default();
    let _ = EvaluateRequest::new("1 + 1");
    let _ = ScreenshotRequest::default();
    let _ = Action::Fill {
        target: Target::parse("#email"),
        value: "someone@example.com".to_string(),
    };
    let _ = Target::locator(Locator::new(LocateBy::Role, "button").with_name("Submit"));
}

#[test]
fn defaults_are_the_ones_the_contract_documents() {
    assert_eq!(NavigateRequest::new("x").wait_until, WaitUntil::Load);
    assert_eq!(ReadRequest::default().format, ReadFormat::Markdown);
    assert!(SessionOptions::default().headless);
}

#[test]
fn errors_carry_the_wire_names_a_host_matches_on() {
    assert_eq!(
        Error::invalid_input("bad").wire_name(),
        errors::INVALID_INPUT
    );
    assert!(errors::is_agent_recoverable(errors::NO_SUCH_ELEMENT));
    assert!(!errors::is_agent_recoverable(errors::BROWSER_UNAVAILABLE));
}

#[tokio::test]
async fn an_unknown_session_is_reported_without_a_browser() {
    let browser = Browser::new();
    let error = browser
        .navigate(&SessionId::new("never-opened"), &NavigateRequest::new("x"))
        .await
        .expect_err("refused");

    assert!(matches!(error, Error::NoSuchSession { .. }), "{error}");
    assert_eq!(error.wire_name(), errors::NO_SUCH_SESSION);
}

#[tokio::test]
async fn teardown_is_idempotent_for_consumers() {
    // A host retrying a close or a release after a timeout must not have to tell
    // "never existed" apart from "already cleaned up".
    let browser = Browser::new();

    assert!(browser.close_session(&SessionId::new("gone")).await.is_ok());
    assert!(browser.release_output(&OutputId::new("gone")).await.is_ok());
}

//! End-to-end tests against a real browser.
//!
//! # Why these are behind an environment variable
//!
//! Everything else in this repository is deterministic and needs nothing but a
//! Rust toolchain. These need a Chrome, and a CI runner without one would fail
//! them for a reason that has nothing to do with the change under test. So they
//! are opt-in and named `live_*`, per this repository's testing rules:
//!
//! ```sh
//! TINYBROWSER_LIVE_TESTS=1 cargo test -p tinybrowser --test live_chrome
//! ```
//!
//! An environment variable rather than a Cargo feature because the contract
//! command is `cargo test --all-features`, and a feature would be switched on by
//! exactly the command that must keep passing on a machine with no browser.
//!
//! They are still hermetic in the way that matters: every page they drive is
//! served by a one-shot HTTP server this file starts on loopback, so nothing
//! here touches the network and no assertion depends on a website that can
//! change underneath it.
//!
//! Loopback rather than a `data:` URL because the module refuses to navigate to
//! anything but `http`, `https`, and `about:blank` — a policy worth keeping, and
//! one a test suite should be bound by rather than exempt from.
//!
//! # Opted in, they fail rather than skip
//!
//! Setting the variable is the opt-in. Having opted in, a run that cannot find a
//! browser fails: a suite that quietly skips reports green for a build in which
//! nothing was checked, which is worse than no suite at all.
//!
//! On a host where Chrome needs extra flags — no usable sandbox, most often —
//! pass them through:
//!
//! ```sh
//! TINYBROWSER_CHROME=/path/to/chrome \
//! TINYBROWSER_TEST_ARGS=--no-sandbox \
//!   cargo test -p tinybrowser --features live-chrome
//! ```
//!
//! # What they are for
//!
//! The unit suites cover every decision this crate makes *around* the protocol.
//! What they cannot cover is whether the protocol conversation is right — that a
//! ref resolves to the node the snapshot named, that a dispatched click reaches
//! a handler, that a covered element is refused. That is the whole of what these
//! check, and it is the part that would otherwise only be discovered in
//! production.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use base64::Engine as _;
use tinybrowser::{
    Action, Browser, Error, ImageFormat, LocateBy, Locator, NavigateRequest, ReadFormat,
    ReadRequest, ScreenshotRequest, ScrollDirection, SessionInfo, SessionOptions, SnapshotRequest,
    Target, WaitState, WaitUntil,
};
use tokio::io::{AsyncReadExt as _, AsyncWriteExt as _};

/// Serves `body` as a complete HTML document on loopback, and returns its URL.
///
/// One connection per request and no routing: every test wants exactly one page,
/// and a server with fewer moving parts is one that cannot fail in a way that
/// looks like the module failing.
async fn serve(body: &str) -> String {
    let document = format!(
        "<!doctype html><html><head><title>tinybrowser</title></head><body>{body}</body></html>"
    );

    let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
        .await
        .expect("binds a loopback port");
    let address = listener.local_addr().expect("has an address");

    tokio::spawn(async move {
        loop {
            let Ok((mut stream, _)) = listener.accept().await else {
                return;
            };
            let document = document.clone();
            tokio::spawn(async move {
                // Read and discard the request: a server that replies without
                // draining can have the write fail on it.
                let mut scratch = [0_u8; 2048];
                let _ = stream.read(&mut scratch).await;

                let response = format!(
                    "HTTP/1.1 200 OK\r\n\
                     Content-Type: text/html; charset=utf-8\r\n\
                     Content-Length: {}\r\n\
                     Connection: close\r\n\r\n{document}",
                    document.len()
                );
                let _ = stream.write_all(response.as_bytes()).await;
                let _ = stream.shutdown().await;
            });
        }
    });

    format!("http://{address}/")
}

/// Whether this run opted in.
///
/// Returning `false` here is the *only* skip in this file, and it is the one a
/// reader can see at the top of every test.
fn enabled() -> bool {
    std::env::var("TINYBROWSER_LIVE_TESTS").is_ok_and(|value| !value.is_empty() && value != "0")
}

/// The session options these tests open with.
///
/// `TINYBROWSER_TEST_ARGS` is how a host whose Chrome needs extra flags supplies
/// them without those flags becoming this module's defaults.
fn options() -> SessionOptions {
    SessionOptions {
        args: std::env::var("TINYBROWSER_TEST_ARGS")
            .unwrap_or_default()
            .split_whitespace()
            .map(str::to_string)
            .collect(),
        ..SessionOptions::default()
    }
}

/// An engine with one session on `body`.
async fn on(body: &str) -> (Browser, SessionInfo) {
    let browser = Browser::new();
    let session = browser
        .open_session(options())
        .await
        .expect("a browser is available; see this file's docs");

    browser
        .navigate(&session.id, &NavigateRequest::new(serve(body).await))
        .await
        .expect("navigates");

    (browser, session)
}

#[tokio::test]
async fn live_navigating_reports_where_the_page_landed() {
    if !enabled() {
        return;
    }
    let (browser, session) = on("<h1>Hello</h1>").await;

    let state = browser
        .navigate(
            &session.id,
            &NavigateRequest {
                url: serve("<h1>Second</h1>").await,
                wait_until: WaitUntil::DomContentLoaded,
                timeout_ms: Some(10_000),
            },
        )
        .await
        .expect("navigates");

    assert_eq!(state.title, "tinybrowser");
    assert!(state.url.starts_with("http://127.0.0.1:"), "{}", state.url);
    // The status comes from the response the navigation actually received, which
    // is the one thing a caller cannot recover from the URL alone.
    assert_eq!(state.status, Some(200));
    browser.close_session(&session.id).await.expect("closes");
}

#[tokio::test]
async fn live_a_snapshot_ref_resolves_to_the_element_it_named() {
    if !enabled() {
        return;
    }
    // The single most important property in the crate: an agent acts on the ref
    // it read, and the node behind it is the one the snapshot described.
    let (browser, session) = on("<button id='a'>Alpha</button><button id='b'>Beta</button>\
         <script>document.body.onclick = (e) => { document.title = e.target.id; };</script>")
    .await;

    let snapshot = browser
        .snapshot(&session.id, &SnapshotRequest::interactive())
        .await
        .expect("snapshots");

    let beta = snapshot
        .refs
        .iter()
        .find(|element| element.name == "Beta")
        .expect("the second button is in the snapshot");

    let outcome = browser
        .perform(
            &session.id,
            &Action::Click {
                target: Target::reference(&beta.id),
                new_tab: false,
            },
        )
        .await
        .expect("clicks");

    assert_eq!(outcome.page.title, "b");
    browser.close_session(&session.id).await.expect("closes");
}

#[tokio::test]
async fn live_a_ref_from_a_previous_snapshot_is_refused() {
    if !enabled() {
        return;
    }
    let (browser, session) = on("<button>Alpha</button>").await;

    let first = browser
        .snapshot(&session.id, &SnapshotRequest::interactive())
        .await
        .expect("snapshots");
    let reference = first.refs.first().expect("a ref").id.clone();

    // Navigating replaces the document, so every outstanding ref names a node
    // that is gone. Acting on one must say so rather than resolve to whatever
    // now occupies that position.
    browser
        .navigate(
            &session.id,
            &NavigateRequest::new(serve("<button>Beta</button>").await),
        )
        .await
        .expect("navigates");

    let error = browser
        .perform(
            &session.id,
            &Action::Click {
                target: Target::reference(&reference),
                new_tab: false,
            },
        )
        .await
        .expect_err("refused");

    assert!(matches!(error, Error::StaleRef { .. }), "{error}");
    browser.close_session(&session.id).await.expect("closes");
}

#[tokio::test]
async fn live_a_covered_element_is_refused_and_the_cover_is_named() {
    if !enabled() {
        return;
    }
    // A click dispatched at a point a banner covers is delivered to the banner,
    // and without this check the caller is told it succeeded.
    let (browser, session) = on(
        "<button id='target' style='position:fixed;top:50px;left:50px'>Buy</button>\
         <div id='banner' style='position:fixed;inset:0;background:#000'>Consent</div>",
    )
    .await;

    let error = browser
        .perform(
            &session.id,
            &Action::Click {
                target: Target::selector("#target"),
                new_tab: false,
            },
        )
        .await
        .expect_err("refused");

    assert!(matches!(error, Error::NotActionable { .. }), "{error}");
    assert!(error.to_string().contains("banner"), "{error}");
    browser.close_session(&session.id).await.expect("closes");
}

