        "<form action='{destination}' method='get'>\
           <input id='q' name='q'><button type='submit'>Go</button>\
         </form>"
    ))
    .await;

    browser
        .perform(
            &session.id,
            &Action::Focus {
                target: Target::selector("#q"),
            },
        )
        .await
        .expect("focuses");
    let outcome = browser
        .perform(
            &session.id,
            &Action::Press {
                key: "Enter".to_string(),
            },
        )
        .await
        .expect("presses");

    assert!(
        outcome.page.url.starts_with(&destination),
        "expected the submission to land on {destination}, but the page is at {}",
        outcome.page.url
    );

    let text = browser
        .read_page(&session.id, &ReadRequest::default())
        .await
        .expect("reads");
    assert!(text.content.contains("Submitted"), "{}", text.content);

    browser.close_session(&session.id).await.expect("closes");
}

#[tokio::test]
async fn live_a_click_that_navigates_nowhere_does_not_stall() {
    if !enabled() {
        return;
    }
    // The cost of the rule above is paid by every click that starts nothing, so
    // it has to stay small: a menu opening must not wait out a page load.
    let (browser, session) =
        on("<button id='b' onclick=\"document.title = 'opened'\">Menu</button>").await;

    let started = std::time::Instant::now();
    let outcome = browser
        .perform(
            &session.id,
            &Action::Click {
                target: Target::selector("#b"),
                new_tab: false,
            },
        )
        .await
        .expect("clicks");
    let elapsed = started.elapsed();

    assert_eq!(outcome.page.title, "opened");
    assert!(
        elapsed < std::time::Duration::from_secs(3),
        "a click that navigated nowhere took {elapsed:?}"
    );

    browser.close_session(&session.id).await.expect("closes");
}

//! Tests for the snapshot payload types.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use super::{ElementRef, Snapshot, SnapshotRequest};
use serde_json::json;

#[test]
fn snapshot_defaults_to_the_whole_bounded_tree() {
    let request = SnapshotRequest::default();

    assert!(!request.interactive_only);
    assert!(request.selector.is_none());
    assert_eq!(request.max_chars, 200_000);
    assert_eq!(
        serde_json::from_value::<SnapshotRequest>(json!({})).expect("deserializes"),
        request
    );
}

#[test]
fn interactive_keeps_every_other_default() {
    let request = SnapshotRequest::interactive();

    assert!(request.interactive_only);
    assert_eq!(request.max_chars, SnapshotRequest::default().max_chars);
}

#[test]
fn request_serializes_with_the_documented_field_names() {
    let encoded = serde_json::to_value(SnapshotRequest::default()).expect("serializes");
    let mut keys: Vec<&str> = encoded
        .as_object()
        .expect("an object")
        .keys()
        .map(String::as_str)
        .collect();
    keys.sort_unstable();

    assert_eq!(
        keys,
        [
            "compact",
            "depth",
            "include_urls",
            "interactive_only",
            "max_chars",
            "selector",
        ]
    );
}

#[test]
fn snapshot_round_trips() {
    let snapshot = Snapshot {
        url: "https://example.com/".to_string(),
        title: "Example Domain".to_string(),
        sequence: 1,
        tree: "- document \"Example Domain\"\n  - link \"More information\" @e1".to_string(),
        refs: vec![ElementRef {
            id: "e1".to_string(),
            role: "link".to_string(),
            name: "More information".to_string(),
        }],
        truncated: false,
    };

    let encoded = serde_json::to_value(&snapshot).expect("serializes");
    assert_eq!(encoded["refs"][0]["id"], json!("e1"));
    assert_eq!(
        serde_json::from_value::<Snapshot>(encoded).expect("deserializes"),
        snapshot
    );
}

#[test]
fn refs_are_named_without_their_marker() {
    // The `@` belongs to the rendered tree, not to the identity: `Target::parse`
    // strips it, and a ref that carried it would round-trip to `@@e1`.
    let element = ElementRef {
        id: "e1".to_string(),
        role: "link".to_string(),
        name: "More information".to_string(),
    };

    assert!(!element.id.starts_with('@'));
}

//! Unit tests for the contract version and its bind rule.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use super::{CONTRACT_VERSION, binds, is_compatible};

#[test]
fn the_shipped_contract_version_is_pinned() {
    assert_eq!(CONTRACT_VERSION, (1, 0));
}

#[test]
fn the_contract_binds_to_itself() {
    assert!(is_compatible(CONTRACT_VERSION));
}

#[test]
fn a_newer_minor_on_the_module_side_binds() {
    assert!(is_compatible((1, 1)));
    assert!(is_compatible((1, 97)));
}

#[test]
fn an_older_minor_on_the_module_side_is_rejected() {
    // A host built against 1.4 cannot call a 1.2 module: the members it names
    // may not be served.
    assert!(!binds((1, 4), (1, 2)));
    assert!(binds((1, 4), (1, 4)));
}

#[test]
fn a_different_major_is_rejected() {
    assert!(!is_compatible((0, 0)));
    assert!(!is_compatible((2, 0)));
    assert!(!is_compatible((2, 97)));
}

//! Tests for the module's bus identity.
//!
//! These pin strings a host spells from this crate and a module answers to. A
//! change to one of them is a wire break, so it should have to be made twice —
//! once in the constant and once here.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use super::{INTERFACE, METHODS, OBJECT_PATH, methods};

#[test]
fn interface_is_the_published_name() {
    assert_eq!(INTERFACE, "ai.tinyhumans.tinybrowser.Browser");
}

#[test]
fn object_path_is_the_interface_in_path_form() {
    assert_eq!(OBJECT_PATH, "/ai/tinyhumans/tinybrowser/Browser");
    assert_eq!(OBJECT_PATH, format!("/{}", INTERFACE.replace('.', "/")));
}

#[test]
fn methods_lists_every_member_once() {
    let mut sorted = METHODS.to_vec();
    sorted.sort_unstable();
    let count = sorted.len();
    sorted.dedup();

    assert_eq!(sorted.len(), count, "METHODS contains a duplicate");
    assert_eq!(count, 12);
}

#[test]
fn method_constants_are_pascal_case_on_the_wire() {
    for member in METHODS {
        let first = member.chars().next().expect("member name is not empty");
        assert!(first.is_ascii_uppercase(), "{member} is not PascalCase");
        assert!(
            member.chars().all(|c| c.is_ascii_alphanumeric()),
            "{member} is not a bare identifier"
        );
    }
}

#[test]
fn every_member_constant_appears_in_methods() {
    for member in [
        methods::OPEN_SESSION,
        methods::CLOSE_SESSION,
        methods::LIST_SESSIONS,
        methods::NAVIGATE,
        methods::SNAPSHOT,
        methods::PERFORM,
        methods::READ_PAGE,
        methods::EVALUATE,
        methods::SCREENSHOT,
        methods::READ_OUTPUT,
        methods::RELEASE_OUTPUT,
        methods::CONTRACT_VERSION,
    ] {
        assert!(
            METHODS.contains(&member),
            "{member} is missing from METHODS"
        );
    }
}

//! Tests for extraction.
//!
//! The traversal runs in the page, so what is testable here is the boundary
//! around it: the truncation that decides how much of a page a model sees.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use super::truncate;

#[test]
fn content_within_the_limit_is_untouched() {
    let (content, truncated) = truncate("hello".to_string(), 200_000);

    assert_eq!(content, "hello");
    assert!(!truncated);
}

#[test]
fn content_exactly_at_the_limit_is_not_truncated() {
    let (content, truncated) = truncate("hello".to_string(), 5);

    assert_eq!(content, "hello");
    assert!(!truncated);
}

#[test]
fn content_over_the_limit_is_cut_and_reported() {
    // Reporting matters as much as cutting: a model shown a truncated page
    // without being told will conclude the rest of it does not exist.
    let (content, truncated) = truncate("hello world".to_string(), 5);

    assert_eq!(content, "hello");
    assert!(truncated);
}

#[test]
fn truncation_counts_characters_not_bytes() {
    // A byte-wise cut through a multi-byte character produces invalid UTF-8,
    // which would fail to serialize onto the bus rather than returning a short
    // string.
    let (content, truncated) = truncate("héllo wörld".to_string(), 5);

    assert_eq!(content, "héllo");
    assert!(truncated);
    assert_eq!(content.chars().count(), 5);
}

#[test]
fn a_zero_limit_yields_nothing_rather_than_panicking() {
    let (content, truncated) = truncate("hello".to_string(), 0);

    assert!(content.is_empty());
    assert!(truncated);
}

#[test]
fn empty_content_is_never_truncated() {
    let (content, truncated) = truncate(String::new(), 0);

    assert!(content.is_empty());
    assert!(!truncated);
}

//! Tests for the wire error names.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use super::{
    BLOCKED_BY_POLICY, BROWSER_UNAVAILABLE, INVALID_INPUT, LIMIT_EXCEEDED, MODULE_FAILED, NAMES,
    NO_SUCH_ELEMENT, NO_SUCH_OUTPUT, NO_SUCH_SESSION, NOT_ACTIONABLE, PAGE_ERROR, PREFIX,
    STALE_REF, TIMEOUT, is_agent_recoverable,
};

#[test]
fn every_name_sits_under_the_prefix() {
    for name in NAMES {
        assert!(
            name.starts_with(PREFIX),
            "{name} is outside {PREFIX}, so a host matching on the prefix would miss it"
        );
    }
}

#[test]
fn names_lists_every_variant_once() {
    let mut sorted = NAMES.to_vec();
    sorted.sort_unstable();
    let count = sorted.len();
    sorted.dedup();

    assert_eq!(sorted.len(), count, "NAMES contains a duplicate");
    assert_eq!(count, 12);
}

#[test]
fn recoverable_names_are_the_ones_a_model_can_act_on() {
    for name in [
        INVALID_INPUT,
        NO_SUCH_ELEMENT,
        STALE_REF,
        NOT_ACTIONABLE,
        TIMEOUT,
        PAGE_ERROR,
    ] {
        assert!(is_agent_recoverable(name), "{name} should be recoverable");
    }
}

#[test]
fn operator_problems_are_not_offered_back_to_the_model() {
    for name in [
        NO_SUCH_SESSION,
        BLOCKED_BY_POLICY,
        BROWSER_UNAVAILABLE,
        NO_SUCH_OUTPUT,
        LIMIT_EXCEEDED,
        MODULE_FAILED,
    ] {
        assert!(
            !is_agent_recoverable(name),
            "{name} should not be offered back to the model"
        );
    }
}

#[test]
fn an_unknown_name_is_not_recoverable() {
    // A module from a newer contract can send a name this build has never seen.
    // Treating it as recoverable would have an agent retry something it cannot
    // understand; treating it as an operator problem surfaces it instead.
    assert!(!is_agent_recoverable(
        "ai.tinyhumans.tinybrowser.Error.Invented"
    ));
}
